args.command:
cd /workspace && date -u; curl -s "$VERACITY_URL/v1/episodes/VR-488814" | python3 -c "
import json,sys; d=json.load(sys.stdin)
for k in ['episode_id','phase','posting_deadline','challenge_deadline','content_hash','evidence_hash','content','evidence','creator_votes','challenger_votes','required_votes','total_deposited_wei']:
    print(k,':',d[k])
print('jurors:',[(j['actor_id'],j['commitment'],j['revealed'],j['verdict']) for j in d['jurors']])
"

cd /workspace && curl -s "$VERACITY_URL/v1/episodes/VR-488814/forum/messages" | python3 -c "
import json,sys; d=json.load(sys.stdin); print(len(d['messages']),'messages')
for m in d['messages']: print('---',m['sequence'],m['sender_id']); print(m['content'][:1400]); print()
"; echo '--- chats ---'; curl -s "$VERACITY_URL/v1/episodes/VR-488814/chats" | head -c 300

cd /workspace && cat > forum_body.json <<'EOF'
{"content":"Challenged. The September reconciliation does not show equal adjusted balances. Adjusted bank balance: 18,642.35 + 2,150.00 deposit in transit - 480.00 (cheque 1043) - 1,215.40 (cheque 1047) - 96.25 (cheque 1049) = 19,000.70. Adjusted book balance: 19,290.70 - 40.00 bank charges not yet entered = 19,250.70. They differ by 250.00, so the claim that they are equal does not hold. The preparer's note 'Reconciled, no differences' and the statement that no other reconciling items were identified do not close the gap: they assert a conclusion the printed arithmetic contradicts, and an unreconciled 250.00 is exactly the item that would have been listed had it been found. To agree, the book side would need 19,000.70 (cash book 19,040.70) or the bank side +250.00 more; neither appears in the schedule. For completeness, the unadjusted figures differ by 648.35, and the listed items explain only 358.35 on the bank side and 40.00 on the book side, leaving the 250.00. Uncertainty: this schedule is the only document in the case, so the individual figures are taken as printed - the defect is in the printed arithmetic, not in missing paperwork."}
EOF
curl -s -X POST "$VERACITY_URL/v1/episodes/VR-488814/forum/messages" -H "Content-Type: application/json" -H "Idempotency-Key: vr488814-forum-1" --data-binary @forum_body.json | python3 -c "
import json,sys; d=json.load(sys.stdin); print('seq',d['sequence'],d['sender_id'],d['content_hash'])
"

cd /workspace && date -u; curl -s "$VERACITY_URL/v1/episodes/VR-488814" | python3 -c "
import json,sys; d=json.load(sys.stdin)
print('phase:',d['phase'],'| commit_deadline:',d['commit_deadline'],'| reveal_deadline:',d['reveal_deadline'])
print('evidence set:',d['evidence'] is not None,'hash:',d['evidence_hash'])
print('deposited:',d['total_deposited_wei'])
for j in d['jurors']: print(' ',j['actor_id'],'committed:',j['commitment'] is not None,'revealed:',j['revealed'],'verdict:',j['verdict'])
"; echo '--- forum ---'; curl -s "$VERACITY_URL/v1/episodes/VR-488814/forum/messages" | python3 -c "
import json,sys; d=json.load(sys.stdin); print(len(d['messages']),'msgs:',[m['sender_id'] for m in d['messages']])
for m in d['messages'][:1]: print('---',m['sequence'],m['sender_id']); print(m['content'][:1000])
"

